'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray-base-numel-dimension' );
var getStride = require( '@stdlib/ndarray-base-stride' );
var getOffset = require( '@stdlib/ndarray-base-offset' );
var getData = require( '@stdlib/ndarray-base-data-buffer' );
var strided = require( '@stdlib/blas-ext-base-gwaxpb' ).ndarray;
var ndarraylike2scalar = require( '@stdlib/ndarray-base-ndarraylike2scalar' );


// MAIN //

/**
* Multiplies each element in an input one-dimensional ndarray by a scalar constant and adds a scalar constant before assigning the results to elements in a one-dimensional output ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant to multiply.
*     -   a zero-dimensional ndarray containing the scalar constant to add.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* var vector = require( '@stdlib/ndarray-vector-ctor' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
*
* var x = vector( [ -2.0, 1.0, 3.0, -5.0 ], 'generic' );
* var w = vector( [ 0.0, 0.0, 0.0, 0.0 ], 'generic' );
*
* var alpha = scalar2ndarray( 5.0, {
*     'dtype': 'generic'
* });
*
* var beta = scalar2ndarray( 3.0, {
*     'dtype': 'generic'
* });
*
* var out = gwaxpb( [ x, w, alpha, beta ] );
* // returns <ndarray>[ -7.0, 8.0, 18.0, -22.0 ]
*
* var bool = ( out === w );
* // returns true
*/
function gwaxpb( arrays ) {
	var alpha;
	var beta;
	var x;
	var w;

	x = arrays[ 0 ];
	w = arrays[ 1 ];
	alpha = ndarraylike2scalar( arrays[ 2 ] );
	beta = ndarraylike2scalar( arrays[ 3 ] );
	strided( numelDimension( x, 0 ), alpha, beta, getData( x ), getStride( x, 0 ), getOffset( x ), getData( w ), getStride( w, 0 ), getOffset( w ) ); // eslint-disable-line max-len
	return w;
}


// EXPORTS //

module.exports = gwaxpb;
